import JSON
import SpecialFunctions: erf

"""
	gen( t, sigma, name )

Generate half-normal MGF fixture data and write to file.

# Arguments

* `t`: input values
* `sigma`: scale parameters
* `name::AbstractString`: output filename
"""
function gen( t, sigma, name )
	z = Array{Float64}( undef, length(t) )

	for i in eachindex(t)
		z[i] = exp( 0.5 * sigma[i]^2 * t[i]^2 ) *
			( 1.0 + erf( sigma[i] * t[i] / sqrt(2.0) ) )
	end

	data = Dict([
		("x", t),
		("sigma", sigma),
		("expected", z)
	])

	filepath = joinpath( dir, name )
	open( filepath, "w" ) do io
		write( io, JSON.json( data ) )
		write( io, "\n" )
	end
end

# Get script directory:
file = @__FILE__
dir = dirname( file )

# ------------------------
# Positive t
# ------------------------
t = rand( 1000 ) .* 5.0
sigma = rand( 1000 ) .* 5.0 .+ 0.1
gen( t, sigma, "positive_t.json" )

# ------------------------
# Negative t
# ------------------------
t = -rand( 1000 ) .* 5.0
sigma = rand( 1000 ) .* 5.0 .+ 0.1
gen( t, sigma, "negative_t.json" )

# ------------------------
# Large scale (sigma)
# ------------------------
t = rand( 1000 )
sigma = rand( 1000 ) .* 20.0 .+ 5.0
gen( t, sigma, "large_scale.json" )
